import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Version 1.0.0.39 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.39-released.md","filePath":"change-log/release/version-1.0.0.39-released.md"}'),o={name:"change-log/release/version-1.0.0.39-released.md"};function n(l,e,s,d,u,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="version-1-0-0-39-released" tabindex="-1">Version 1.0.0.39 Released <a class="header-anchor" href="#version-1-0-0-39-released" aria-label="Permalink to &quot;Version 1.0.0.39 Released&quot;">​</a></h1><p>Version <strong>1.0.0.39</strong> is a <strong>major milestone release</strong>, introducing a new Tier-1 broker (Kotak), expanding MultiQuote capabilities, and delivering extensive performance, stability, and data-pipeline improvements.</p><hr><h3 id="_0-mandatory-upgrade-notice" tabindex="-1"><strong>0. Mandatory Upgrade Notice</strong> <a class="header-anchor" href="#_0-mandatory-upgrade-notice" aria-label="Permalink to &quot;**0. Mandatory Upgrade Notice**&quot;">​</a></h3><p>This version <strong>requires mandatory upgrade steps</strong> due to new DB indexes, migration updates, and broker integrations.</p><p>Upgrade guide:<br><a href="https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade" target="_blank" rel="noreferrer"><strong>https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade</strong></a></p><hr><h3 id="_1-major-new-integration-motilal-oswal-added" tabindex="-1"><strong>1. Major New Integration: Motilal Oswal Added</strong> <a class="header-anchor" href="#_1-major-new-integration-motilal-oswal-added" aria-label="Permalink to &quot;**1. Major New Integration: Motilal Oswal Added**&quot;">​</a></h3><p>Tradeboard now officially includes <strong>full Motilal Oswal Integration</strong>.</p><p><strong>Motilal Oswal Integration Includes</strong></p><ul><li>Order placement, modification, cancellation</li><li>Funds, positions, holdings</li><li>WebSocket support</li><li>Margin API</li><li>Contract &amp; exchange mapping</li><li>Fully production-ready routing</li></ul><p>Motilal joins Angel, Dhan, Zerodha, Fyers, Upstox, and Kotak as a primary supported broker.</p><p>This is one of the <strong>largest broker integrations since Tradeboard launched</strong>.</p><hr><h3 id="_2-multiquote-api-–-pilot-release" tabindex="-1"><strong>2. MultiQuote API – Pilot Release</strong> <a class="header-anchor" href="#_2-multiquote-api-–-pilot-release" aria-label="Permalink to &quot;**2. MultiQuote API – Pilot Release**&quot;">​</a></h3><p>A new-generation <strong>MultiQuote API</strong> has been introduced.</p><p><strong>Pilot Launch</strong></p><ul><li><strong>Fyers MultiQuote API</strong> added.</li><li>Designed for ultra-fast multi-symbol quote retrieval.</li></ul><p>MultiQuote provides low-latency quotes for scanners, dashboards, and strategies.</p><p><em>(Further broker rollout will occur in upcoming versions.)</em></p><hr><h3 id="_3-platform-improvements" tabindex="-1"><strong>3. Platform Improvements</strong> <a class="header-anchor" href="#_3-platform-improvements" aria-label="Permalink to &quot;**3. Platform Improvements**&quot;">​</a></h3><h4 id="websocket-verbose-mode" tabindex="-1"><strong>WebSocket Verbose Mode</strong> <a class="header-anchor" href="#websocket-verbose-mode" aria-label="Permalink to &quot;**WebSocket Verbose Mode**&quot;">​</a></h4><ul><li>New toggleable verbose mode to reduce noise and improve streaming efficiency.</li></ul><h4 id="database-latency-engine" tabindex="-1"><strong>Database &amp; Latency Engine</strong> <a class="header-anchor" href="#database-latency-engine" aria-label="Permalink to &quot;**Database &amp; Latency Engine**&quot;">​</a></h4><ul><li>Added multiple high-impact DB indexes.</li><li>Unified migration system implemented.</li><li>Latency stats optimized (N+1 query fix).</li><li>latency.db storage trimmed by removing heavy request/response data.</li></ul><h4 id="pnltracker" tabindex="-1"><strong>PNLTracker</strong> <a class="header-anchor" href="#pnltracker" aria-label="Permalink to &quot;**PNLTracker**&quot;">​</a></h4><ul><li>Now supports <strong>sub-minute trades</strong> for precise scalping and HFT-style analytics.</li></ul><h4 id="python-sdk-v1-0-40" tabindex="-1"><strong>Python SDK v1.0.40</strong> <a class="header-anchor" href="#python-sdk-v1-0-40" aria-label="Permalink to &quot;**Python SDK v1.0.40**&quot;">​</a></h4><ul><li>Updated for compatibility with v1.0.0.39.</li><li>Enhanced WebSocket support with verbose control.</li></ul><hr><h3 id="_4-major-motilal-enhancements" tabindex="-1"><strong>4. Major Motilal Enhancements</strong> <a class="header-anchor" href="#_4-major-motilal-enhancements" aria-label="Permalink to &quot;**4. Major Motilal Enhancements**&quot;">​</a></h3><p><strong>WebSocket Updates</strong></p><ul><li>Normalized depth levels 2–5 (set to zero values).</li><li>Fixed depth feed and LTP updates for Index symbols.</li><li>Full LTP + quotes + 1-level depth implemented.</li><li>SSL certificate issue handled by disabling SSL until broker fixes.</li></ul><p><strong>Market Data &amp; Contracts</strong></p><ul><li>Master contract updated with Index contracts.</li><li>Historical API aligned with new contract updates.</li><li>Index quote logic improved.</li></ul><p><strong>Orders, Margin &amp; Holdings</strong></p><ul><li>Quantity-to-lot conversion fixed.</li><li>Minor order API bugs resolved.</li><li>Holdings API updated and stabilized.</li><li>Margin API enhanced.</li></ul><hr><h3 id="_5-options-engine-enhancements" tabindex="-1"><strong>5. Options Engine Enhancements</strong> <a class="header-anchor" href="#_5-options-engine-enhancements" aria-label="Permalink to &quot;**5. Options Engine Enhancements**&quot;">​</a></h3><p><strong>OptionsMultiOrder</strong></p><ul><li>Response formatting fixed.</li><li>Underlying LTP “None” issue resolved.</li><li>Multi-quote underlying resolution improved.</li><li>Multiple fixes based on PR review.</li></ul><p><strong>Options APIs</strong></p><ul><li>Cleanup and parameter corrections across OptionsOrder and OptionSymbol.</li></ul><hr><h3 id="_6-additional-broker-level-improvements" tabindex="-1"><strong>6. Additional Broker-Level Improvements</strong> <a class="header-anchor" href="#_6-additional-broker-level-improvements" aria-label="Permalink to &quot;**6. Additional Broker-Level Improvements**&quot;">​</a></h3><p><strong>Dhan</strong></p><ul><li>depth_level fixes.</li><li>Depth 5/20 activation.</li><li>unsubscribe_all fixed.</li></ul><p><strong>Fyers</strong></p><ul><li>TBT unsubscription fixed.</li><li>TBT 50-level depth upgraded.</li></ul><p><strong>Zebu, PayTM, TradeJini</strong></p><ul><li>Margin APIs updated (standardized for non-margin brokers).</li></ul><p><strong>General</strong></p><ul><li>Multiple contract mapping and feed consistency fixes across brokers.</li></ul><hr><h3 id="_7-ui-security-documentation" tabindex="-1"><strong>7. UI, Security &amp; Documentation</strong> <a class="header-anchor" href="#_7-ui-security-documentation" aria-label="Permalink to &quot;**7. UI, Security &amp; Documentation**&quot;">​</a></h3><ul><li>Design documentation updated for November release.</li><li>Security updates including IDOR fixes and safer endpoint routing.</li><li>Removed unused login decorators from Playground.</li><li>Navigation/UI clean-ups.</li><li>Migration scripts updated for order mode changes.</li></ul><hr><h3 id="summary" tabindex="-1"><strong>Summary</strong> <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;**Summary**&quot;">​</a></h3><p>Version <strong>1.0.0.39</strong> introduces:</p><ul><li><strong>Full Kotak integration</strong></li><li><strong>Pilot MultiQuote API for Fyers</strong></li><li><strong>Mandatory upgrade procedure</strong></li><li>Major Motilal WebSocket, depth &amp; contract fixes</li><li>Database indexing &amp; latency engine optimizations</li><li>Sub-minute PNL tracking</li><li>WebSocket verbose mode</li><li>Python SDK 1.0.40</li><li>Dozens of broker stability improvements</li></ul><p>This release significantly strengthens Tradeboard’s real-time data layer, multi-broker coverage, and execution reliability.</p><hr><hr>',64)])])}const m=t(o,[["render",n]]);export{c as __pageData,m as default};
